const { readArchiveJsonEntries } = require('./modpack-archive');
const { deduplicateTasks, libraryTasks, throwIfAborted } = require('./downloader');
const { validateVersionMetadata } = require('./metadata-schema');

// Read only metadata from the already verified installer. Empty artifact URLs
// describe files embedded in the JAR or generated by its processors, not remote
// downloads (for example Forge's client/extra/slim artifacts).
async function installerLibraryTasks(installerPath, gameDirectory, sourceManager, preferredSourceId, signal) {
  const entries = await readArchiveJsonEntries(installerPath, ['install_profile.json', 'version.json'], { signal });
  throwIfAborted(signal);
  const profile = entries['install_profile.json'];
  if (!profile || typeof profile !== 'object' || Array.isArray(profile)) {
    throw new Error('加载器安装器缺少有效的 install_profile.json');
  }
  const documents = [profile, entries['version.json'] ?? profile.versionInfo].filter(Boolean);
  const libraries = [];
  for (const document of documents) {
    if (typeof document !== 'object' || Array.isArray(document)
        || (document.libraries !== undefined && !Array.isArray(document.libraries))) {
      throw new Error('加载器安装器依赖清单格式无效');
    }
    for (const library of document.libraries ?? []) {
      if (!library || typeof library !== 'object') throw new Error('加载器安装器依赖库格式无效');
      if (library.clientreq === false) continue;
      if (library.downloads) {
        if (!library.downloads.artifact?.url) continue;
      } else if (library.name === profile.install?.path) {
        // Legacy Forge copies its own universal JAR out of the installer.
        continue;
      }
      libraries.push(library);
    }
  }
  // Empty URLs are valid for generated/embedded installer artifacts. Validate
  // only the remote libraries against the normal launch library schema.
  validateVersionMetadata({ libraries });
  const tasks = deduplicateTasks(libraryTasks({ libraries }, gameDirectory, sourceManager, preferredSourceId));
  for (const task of tasks) {
    if (task.urls.some((value) => {
      const url = new URL(value);
      return !['https:', 'http:'].includes(url.protocol) || url.username || url.password;
    })) throw new Error('加载器依赖库下载地址无效');
  }
  return tasks;
}

module.exports = { installerLibraryTasks };
